-- cu9h t02 bombing-run probe: galactic story script of the campaign "CU9H PROBE: BOMBING RUN" (generated by
-- tools/probe_mod/cu9h_bombing/build_cu9h_mod.py from cu9h_story.lua). It starts the land battle by itself:
-- 3 s after the galaxy starts (story event CU9H_Begin, STORY_ELAPSED) it spawns the defenders on @@TARGET@@ for the
-- Empire, the human Rebel's bombers + ground units on @@SOURCE@@, assembles them into ONE fleet, moves it to @@TARGET@@
-- and calls fleet.Invade(). This is the S10 probe's sequence (tools/probe_mod/s10_map_owners/s10_story.lua), which
-- started a land invasion at once in retail when the fleet's owner is the local (human) player (A1_READINGS sec. 31).
-- The Y-Wing squadrons stay in orbit, so the battle's attacker has bombers in orbit (L1_S4_REMAINING sec. 3.7).
-- Arms only when the Rebel player is human. Calls that may fail are wrapped in pcall (a failed engine call silently
-- kills a retail script); progress is shown with Game_Message (retail shows no _MessagePopup). When no "moving"
-- message appears, the driver invades by hand (README).
require("PGStoryMode")

CU9H_TARGET = "@@TARGET@@"
CU9H_SOURCE = "@@SOURCE@@"
CU9H_ATTACK = { @@ATTACK@@ }
CU9H_DEFENSE = { @@DEFENSE@@ }

function Definitions()
	StoryModeEvents = { CU9H_Begin = CU9H_State_Begin }
	CU9H_Started = false
end

function CU9H_Say(text_id)
	pcall(Game_Message, text_id)
end

function CU9H_State_Begin(message)
	if message == OnEnter and not CU9H_Started then
		CU9H_Started = true
		Create_Thread("CU9H_Invade")
	end
end

function CU9H_Count(t)
	local n = 0
	if type(t) == "table" then
		for _, _ in pairs(t) do
			n = n + 1
		end
	end
	return n
end

function CU9H_Invade()
	local ok, reb = pcall(Find_Player, "Rebel")
	local ok2, emp = pcall(Find_Player, "Empire")
	if not ok or not ok2 or reb == nil or emp == nil then
		CU9H_Say("TEXT_CU9H_LUA_FAIL")
		return
	end
	local okh, human = pcall(function() return reb.Is_Human() end)
	if not okh or not human then
		CU9H_Say("TEXT_CU9H_LUA_NOT_HUMAN")
		return
	end
	local src = FindPlanet(CU9H_SOURCE)
	local tgt = FindPlanet(CU9H_TARGET)
	if not TestValid(src) or not TestValid(tgt) then
		CU9H_Say("TEXT_CU9H_LUA_FAIL")
		return
	end
	-- SpawnList / Assemble_Fleet / BlockOnCommand are called as the S10 script calls them (BlockOnCommand yields,
	-- and Lua 5.0 cannot yield across pcall)
	SpawnList(CU9H_DEFENSE, tgt, emp, true, false)
	local units = SpawnList(CU9H_ATTACK, src, reb, false, false)
	if CU9H_Count(units) == 0 then
		CU9H_Say("TEXT_CU9H_LUA_FAIL")
		return
	end
	local fleet = Assemble_Fleet(units)
	if not TestValid(fleet) then
		CU9H_Say("TEXT_CU9H_LUA_FAIL")
		return
	end
	CU9H_Say("TEXT_CU9H_LUA_MOVING")
	BlockOnCommand(fleet.Move_To(tgt))
	Sleep(1)
	local oki = pcall(function() fleet.Invade() end)
	if oki then
		CU9H_Say("TEXT_CU9H_LUA_INVADE")
	else
		CU9H_Say("TEXT_CU9H_LUA_FAIL")
	end
end
